import React from 'react';

const Education = () => {
  const educationData = [
    {
      degree: "Diploma - Computer Engineering",
      institute: "Vallabh Budhi Polytechnic, Navsari",
      year: "2017 - 2020"
    },
    {
      degree: "Bachelor - Computer Engineering",
      institute: "Mahatma Gandhi Institute of Technology, Navsari",
      year: "2020 - 2023"
    },
    {
      degree: "Post Diploma - Mobile Application Development",
      institute: "Fanshawe College, London, Canada",
      year: "2024 - 2025"
    }
  ];

  return (
    <section id="education">
      <h2>Education</h2>
      <ul>
        {educationData.map((edu, index) => (
          <li key={index} style={{ marginBottom: "15px" }}>
            <strong>{edu.degree}</strong> <br />
            {edu.institute} <br />
            <em>{edu.year}</em>
          </li>
        ))}
      </ul>
    </section>
  );
};

export default Education;
